<script setup lang="ts">
import{computed,onMounted,ref}from"vue";
import{auth,nodes,inbounds,clients,traffic,audit,quotas,admins,configs}from"./api";
const sections=[["dashboard","داشبورد","Dashboard"],["nodes","نودها","Nodes"],["inbounds","این‌باندها","Inbounds"],["clients","کلاینت‌ها","Clients"],["traffic","ترافیک و سهمیه","Traffic & Usage"],["admins","مدیران و RBAC","Managers & RBAC"],["audit","گزارش حسابرسی","Audit Logs"],["settings","تنظیمات","Settings"]];
const artifact=ref<any>(null),section=ref("dashboard"),lang=ref<"fa"|"en">("fa"),drawer=ref(false),email=ref(""),password=ref(""),mfaToken=ref(""),mfaCode=ref(""),loginError=ref(""),loading=ref(false),booting=ref(true),me=ref<any>(null),modal=ref<string|null>(null),notice=ref("");
const nodeRows=ref<any[]>([]),inboundRows=ref<any[]>([]),clientRows=ref<any[]>([]),adminRows=ref<any[]>([]),auditRows=ref<any[]>([]),trafficData=ref<any>({}),clientDetail=ref<any>(null),clientDevices=ref<any[]>([]),artifactName=ref("client.conf");
const clientFilters=ref({search:"",status:"",protocol:"",inbound_id:"",online:""});
const nodeForm=ref({name:"",address:"",ssh_port:22,ssh_username:"root",ssh_password:""}),inboundForm=ref({node_id:"",name:"",protocol:"wireguard",listen_port:51820,interface:"wg0",address:"10.10.0.1/24",network:"10.10.0.0/24",dns:"1.1.1.1"}),clientForm=ref({inbound_id:"",name:"",assigned_address:"10.10.0.2/32",expires_at:"",total_gb:"",daily_gb:"",monthly_gb:"",max_devices:"",warning_ratio:80}),adminForm=ref({email:"",password:"",role:"tenant_operator"}),quotaForm=ref({client_id:"",total_bytes:"",daily_bytes:"",monthly_bytes:"",max_devices:"",warning_ratio:80});
const clientEditingId=ref<string|null>(null),inboundEditingId=ref<string|null>(null);
const title=computed(()=>{const s=sections.find(x=>x[0]===section.value);return s?.[lang.value==="fa"?1:2]??(lang.value==="fa"?"داشبورد":"Dashboard")});
const dir=computed(()=>lang.value==="fa"?"rtl":"ltr");
const t=(fa:string,en:string)=>lang.value==="fa"?fa:en;
const nodeOnline=computed(()=>nodeRows.value.filter(n=>["ready","degraded","READY","DEGRADED"].includes(String(n.state||""))).length);
const nodeOffline=computed(()=>Math.max(0,nodeRows.value.length-nodeOnline.value));
const inboundActive=computed(()=>inboundRows.value.filter(x=>["active","ready","ACTIVE","READY"].includes(String(x.state||x.desired_state||""))).length);
const clientActive=computed(()=>clientRows.value.filter(x=>["ACTIVE","active"].includes(String(x.status||x.state||""))).length);
const nodeSearch=ref(""),nodeStateFilter=ref("");
const filteredNodeRows=computed(()=>nodeRows.value.filter(n=>{const q=nodeSearch.value.trim().toLowerCase();return(!q||[n.name,n.address,n.agent_url,n.id].join(" ").toLowerCase().includes(q))&&(!nodeStateFilter.value||String(n.state)===nodeStateFilter.value)}));
const nodeHealthy=computed(()=>nodeRows.value.filter(n=>["READY","DEGRADED"].includes(String(n.state))).length);
const inboundSearch=ref(""),inboundProtocolFilter=ref(""),inboundStateFilter=ref("");
const filteredInboundRows=computed(()=>inboundRows.value.filter(x=>{
 const q=inboundSearch.value.trim().toLowerCase();
 const text=[x.name,x.protocol,x.interface,x.address,x.network,x.node_id,x.id].join(" ").toLowerCase();
 const state=String(x.desired_state||x.state||"").toLowerCase();
 return (!q||text.includes(q))&&(!inboundProtocolFilter.value||String(x.protocol)===inboundProtocolFilter.value)&&(!inboundStateFilter.value||state===inboundStateFilter.value.toLowerCase());
}));
const inboundClientsCount=(id:string)=>clientRows.value.filter(x=>x.inbound_id===id&&x.status!=="REVOKED").length;
const inboundOnlineCount=(id:string)=>clientRows.value.filter(x=>x.inbound_id===id&&x.online).length;
const inboundDisabled=computed(()=>inboundRows.value.filter(x=>x.enabled===false||String(x.desired_state||"").toUpperCase()!=="ACTIVE").length);
const filteredClientRows=computed(()=>{const f=clientFilters.value;return clientRows.value.filter(x=>{const q=f.search.trim().toLowerCase();const text=[x.name,x.assigned_address,x.inbound_name,x.node_name].join(" ").toLowerCase();return(!q||text.includes(q))&&(!f.status||String(x.status).toLowerCase()===f.status.toLowerCase())&&(!f.protocol||String(x.protocol)===f.protocol)&&(!f.inbound_id||x.inbound_id===f.inbound_id)&&(!f.online||String(x.online)===f.online)})});
const clientTrafficTotal=computed(()=>clientRows.value.reduce((s,x)=>s+Number(x.total_traffic||0),0));
const clientOnlineCount=computed(()=>clientRows.value.filter(x=>x.online).length);
const clientExpiringCount=computed(()=>{const n=Date.now()+7*86400000;return clientRows.value.filter(x=>x.expires_at&&new Date(x.expires_at).getTime()<=n&&new Date(x.expires_at).getTime()>Date.now()&&x.status!=="REVOKED").length});
const clientQuotaWarnings=computed(()=>clientRows.value.filter(x=>x.quota_state==="WARNING"||x.quota_state==="LIMIT_REACHED").length);
const trafficTotal=computed(()=>Number(trafficData.value.total_bytes||0));
const trafficIn=computed(()=>Number(trafficData.value.bytes_in||0));
const trafficOut=computed(()=>Number(trafficData.value.bytes_out||0));
const trafficMax=computed(()=>Math.max(trafficIn.value,trafficOut.value,1));
const trafficInPct=computed(()=>Math.round(trafficIn.value/trafficMax.value*100));
const trafficOutPct=computed(()=>Math.round(trafficOut.value/trafficMax.value*100));
const recentActivity=computed(()=>auditRows.value.slice(0,5));
const formatBytes=(n:number)=>{if(!n)return "0 B";const u=["B","KB","MB","GB","TB","PB"];const i=Math.min(Math.floor(Math.log(n)/Math.log(1024)),u.length-1);return (n/Math.pow(1024,i)).toFixed(i?2:0)+" "+u[i]};
const trafficTotalLabel=computed(()=>formatBytes(trafficTotal.value));
const trafficInLabel=computed(()=>formatBytes(trafficIn.value));
const trafficOutLabel=computed(()=>formatBytes(trafficOut.value));
const activityLabel=(x:any)=>{const a=String(x?.action||"Activity");return ({login:"ورود کاربر",node_provision:"Provision نود",node_create:"ایجاد نود",inbound_create:"ایجاد Inbound",inbound_sync:"Sync Inbound",client_create:"ایجاد Client",client_revoke:"Revoke Client",quota_set:"تنظیم سهمیه"} as Record<string,string>)[a]||a};
const activityTone=(x:any)=>{const a=String(x?.action||"");if(a.includes("revoke")||String(x?.result||"").toLowerCase().includes("fail"))return "danger";if(a.includes("provision")||a.includes("create"))return "primary";return "success"};
const refreshDashboard=()=>load();
async function load(){loading.value=true;try{me.value=await auth.me();const[n,i,c,t,a]=await Promise.all([nodes.list(),inbounds.list(),clients.list(),traffic.summary(),audit.list()]);nodeRows.value=n;inboundRows.value=i;clientRows.value=c;trafficData.value=t;if(me.value.role!=="tenant_operator")adminRows.value=await admins.list()}catch(e){if(localStorage.getItem("primevpn_access"))loginError.value=e instanceof Error?e.message:"خطای API"}finally{loading.value=false;booting.value=false}}
async function login(){loginError.value="";loading.value=true;try{const r=await auth.login(email.value,password.value);if(r.mfa_required){mfaToken.value=r.mfa_token;modal.value="mfa";return}localStorage.setItem("primevpn_access",r.access_token);await load()}catch(e){loginError.value=e instanceof Error?e.message:"ورود ناموفق"}finally{loading.value=false}}
async function verifyMfa(){try{const r=await auth.mfaVerify(mfaToken.value,mfaCode.value);localStorage.setItem("primevpn_access",r.access_token);modal.value=null;await load()}catch(e){loginError.value=e instanceof Error?e.message:"کد MFA نامعتبر"}}
async function act(fn:()=>Promise<any>,success="انجام شد"){try{await fn();notice.value=success;modal.value=null;await load()}catch(e){notice.value=e instanceof Error?e.message:"خطا"}}
function clientFilename(protocol:string,name:string){const safe=name.replace(/[^a-zA-Z0-9._-]+/g,"-").replace(/^-+|-+$/g,"")||"client";return safe+(protocol==="openvpn"?".ovpn":".conf")}
function downloadArtifact(){if(!artifact.value?.payload)return;const blob=new Blob([artifact.value.payload],{type:"text/plain;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=artifactName.value;a.click();URL.revokeObjectURL(url);notice.value="فایل کانفیگ دانلود شد"}
async function issueConfig(id:string,autoDownload=false){try{const c=await clients.credential(id);artifact.value=await configs.download(c.artifact_id);const row=clientRows.value.find(x=>x.id===id);artifactName.value=clientFilename(String(artifact.value?.protocol||row?.protocol||"wireguard"),row?.name||"client");modal.value="artifact";if(autoDownload)downloadArtifact()}catch(e){notice.value=e instanceof Error?e.message:"خطا در ساخت Config"}}
async function createClient(){loading.value=true;try{const f=clientForm.value;const gb=(v:string)=>v&&Number(v)>0?Math.round(Number(v)*1024*1024*1024):null;const created=await clients.create({inbound_id:f.inbound_id,name:f.name,assigned_address:f.assigned_address,expires_at:f.expires_at?new Date(f.expires_at).toISOString():null,total_bytes:gb(f.total_gb),daily_bytes:gb(f.daily_gb),monthly_bytes:gb(f.monthly_gb),max_devices:f.max_devices?Number(f.max_devices):null,warning_ratio:Number(f.warning_ratio||80)});modal.value=null;await load();await issueConfig(created.id,true);notice.value="کلاینت ساخته شد و فایل کانفیگ آماده دانلود است"}catch(e){notice.value=e instanceof Error?e.message:"ساخت کلاینت ناموفق"}finally{loading.value=false}}
function resetClientForm(){clientEditingId.value=null;clientForm.value={inbound_id:"",name:"",assigned_address:"10.10.0.2/32",expires_at:"",total_gb:"",daily_gb:"",monthly_gb:"",max_devices:"",warning_ratio:80}}
function openClientEdit(x:any){clientEditingId.value=x.id;clientForm.value={inbound_id:x.inbound_id,name:x.name,assigned_address:x.assigned_address,expires_at:x.expires_at?new Date(x.expires_at).toISOString().slice(0,16):"",total_gb:x.quota_total?String((x.quota_total/1073741824).toFixed(2)):"",daily_gb:x.quota_daily?String((x.quota_daily/1073741824).toFixed(2)):"",monthly_gb:x.quota_monthly?String((x.quota_monthly/1073741824).toFixed(2)):"",max_devices:x.max_devices?String(x.max_devices):"",warning_ratio:x.quota_warning_ratio||80};modal.value="client-edit"}
async function saveClientEdit(){if(!clientEditingId.value)return;loading.value=true;try{const f=clientForm.value;const gb=(v:string)=>v&&Number(v)>0?Math.round(Number(v)*1024*1024*1024):undefined;await clients.update(clientEditingId.value,{name:f.name,expires_at:f.expires_at?new Date(f.expires_at).toISOString():null,total_bytes:gb(f.total_gb),daily_bytes:gb(f.daily_gb),monthly_bytes:gb(f.monthly_gb),max_devices:f.max_devices?Number(f.max_devices):undefined,warning_ratio:Number(f.warning_ratio||80)});notice.value="اطلاعات کلاینت بروزرسانی شد";modal.value=null;await load()}catch(e){notice.value=e instanceof Error?e.message:"بروزرسانی ناموفق"}finally{loading.value=false}}
function openNodeDetail(n:any){clientDetail.value={...n};clientDevices.value=[];modal.value="node-detail"}
function resetInboundForm(){inboundEditingId.value=null;inboundForm.value={node_id:"",name:"",protocol:"wireguard",listen_port:51820,interface:"wg0",address:"10.10.0.1/24",network:"10.10.0.0/24",dns:"1.1.1.1"}}
function openInboundEdit(x:any){inboundEditingId.value=x.id;inboundForm.value={node_id:x.node_id,name:x.name,protocol:x.protocol,listen_port:x.listen_port,interface:x.interface,address:x.address,network:x.network,dns:x.dns||"1.1.1.1"};modal.value="inbound"}
function openInboundDetail(x:any){clientDetail.value={...x};modal.value="inbound-detail"}
async function saveInbound(){loading.value=true;try{if(inboundEditingId.value)await inbounds.update(inboundEditingId.value,inboundForm.value);else await inbounds.create(inboundForm.value);notice.value=inboundEditingId.value?"Inbound بروزرسانی شد":"Inbound ساخته شد";modal.value=null;resetInboundForm();await load()}catch(e){notice.value=e instanceof Error?e.message:"عملیات Inbound ناموفق"}finally{loading.value=false}}
async function openClientDetail(x:any){clientDetail.value=x;clientDevices.value=await clients.devices(x.id);modal.value="client-detail"}
async function revokeClient(id:string){if(!window.confirm("این کلاینت و تمام Credentialهای فعال آن revoke شود؟"))return;await act(()=>clients.revoke(id),"کلاینت revoke شد")}
async function copyArtifact(){if(artifact.value?.payload)await navigator.clipboard.writeText(artifact.value.payload);notice.value="Config کپی شد"}
async function provision(id:string){try{const r=await nodes.provision(id);notice.value=r.bootstrap_token?"Bootstrap token ساخته شد؛ برای نصب Agent استفاده کن":"Provisioning ثبت شد";if(r.bootstrap_token)notice.value=`Bootstrap Token: ${r.bootstrap_token}`;modal.value=null;await load()}catch(e){notice.value=e instanceof Error?e.message:"Provisioning ناموفق"}}
function logout(){localStorage.removeItem("primevpn_access");me.value=null}
onMounted(load);
</script>
<template>
<div v-if="booting" class="app-shell"><main class="main"><div class="panel page"><div class="empty">در حال اتصال به PRIMEVPN Control Plane…</div></div></main></div>
<div v-else-if="!me" class="login-shell"><div class="login-card"><div class="brand"><span class="brand-mark">P</span><div><b>PRIMEVPN</b><small>Control Plane v1.0.0</small></div></div><h1>ورود به پنل</h1><p>مدیریت امن Node، Inbound، Client و Traffic</p><input v-model="email" type="email" placeholder="Email"><input v-model="password" type="password" placeholder="Password" @keyup.enter="login"><button class="primary wide" :disabled="loading" @click="login">{{loading?"در حال ورود…":"ورود"}}</button><div v-if="loginError" class="error-box">{{loginError}}</div></div></div>
<div v-else class="app-shell" :dir="dir">
<div v-if="drawer" class="drawer-backdrop" @click="drawer=false"></div>
<aside class="sidebar" :class="{open:drawer}"><div class="brand"><span class="brand-mark">P</span><div><b>PRIMEVPN</b><small>Control Plane v1.0.0</small></div></div><nav><button v-for="s in sections" :key="s[0]" :class="{active:section===s[0]}" @click="section=s[0];drawer=false"><span class="nav-icon">{{["⌂","♙","▤","◎","▣","◈","⌁","⚙"][sections.indexOf(s)]}}</span><span>{{s[lang==="fa"?1:2]}}</span><small>{{s[lang==="fa"?2:1]}}</small></button></nav><div class="sidebar-foot"><i></i>{{me.email}}<button class="icon" @click="logout">خروج</button></div></aside>
<main class="main"><header><button class="mobile-menu" @click="drawer=true">☰</button><div class="top-brand"><span class="brand-mark">P</span><div><b>PRIME<span>VPN</span></b><small>Secure · Fast · Global</small></div></div><div class="header-spacer"></div><div class="account-pill"><i></i><div><b>{{me.role}}</b><small>Tenant</small></div><span>●</span></div><div class="language"><button :class="{on:lang==='fa'}" @click="lang='fa'">فارسی</button><button :class="{on:lang==='en'}" @click="lang='en'">English</button></div></header><div v-if="notice" class="notice" @click="notice=''">{{notice}}</div>
<div v-if="loading" class="panel"><div class="empty">در حال دریافت داده…</div></div>
<section v-else-if="section==='dashboard'" class="dashboard-home">
<div class="dashboard-toolbar"><div><span class="eyebrow">PRIMEVPN CONTROL PLANE</span><h1>{{t("نمای کلی سیستم","System Overview")}}</h1><p>{{t("وضعیت لحظه‌ای نودها، اینباندها، کلاینت‌ها و مصرف ترافیک","Live overview of nodes, inbounds, clients and traffic")}}</p></div><button class="refresh-btn" :disabled="loading" @click="refreshDashboard">↻ {{t("بروزرسانی","Refresh")}}</button></div>
<div class="welcome-row"><div><small>{{t("خوش آمدید","Welcome back")}}</small><h2>{{me.email}}</h2><div class="service-status"><i></i><b>{{t("Control Plane آنلاین است","Control Plane is online")}}</b><small>API</small></div></div><div class="hero-shield">P</div></div>
<div class="stats dashboard-stats">
<article><span class="stat-icon users">♟</span><small>{{t("کل کلاینت‌ها","Total Clients")}}</small><strong>{{clientRows.length}}</strong><em class="neutral">{{clientActive}} {{t("فعال","active")}}</em></article>
<article><span class="stat-icon nodes">▤</span><small>{{t("نودهای آنلاین","Online Nodes")}}</small><strong>{{nodeOnline}}<small class="of-total"> / {{nodeRows.length}}</small></strong><em class="neutral">{{nodeOffline}} {{t("نود خارج از دسترس","offline")}}</em></article>
<article><span class="stat-icon plans">◎</span><small>{{t("اینباند‌های فعال","Active Inbounds")}}</small><strong>{{inboundActive}}<small class="of-total"> / {{inboundRows.length}}</small></strong><em class="neutral">{{inboundRows.length-inboundActive}} {{t("غیرفعال","inactive")}}</em></article>
<article><span class="stat-icon traffic">⌁</span><small>{{t("کل ترافیک","Total Traffic")}}</small><strong>{{trafficTotalLabel}}</strong><em class="neutral">IN {{trafficInLabel}} · OUT {{trafficOutLabel}}</em></article>
</div>
<div class="dashboard-grid">
<div class="panel traffic-card"><div class="panel-head"><div><h2>{{t("مصرف ترافیک","Traffic Usage")}}</h2><small>{{t("بر اساس داده‌های ثبت‌شده","Based on recorded usage")}}</small></div><span class="live-badge"><i></i>{{t("زنده","Live")}}</span></div>
<div class="traffic-total">{{trafficTotalLabel}}</div>
<div class="traffic-bars"><div class="traffic-row"><span>IN</span><div class="traffic-track"><b :style="{ width: trafficInPct + '%' }"></b></div><strong>{{trafficInLabel}}</strong></div><div class="traffic-row"><span>OUT</span><div class="traffic-track out"><b  :style="{ width: trafficOutPct + '%' }"></b></div><strong>{{trafficOutLabel}}</strong></div></div>
<div class="traffic-foot"><span>{{t("دریافت","Download")}} {{trafficInPct}}%</span><span>{{t("ارسال","Upload")}} {{trafficOutPct}}%</span></div></div>
<div class="panel health-card"><div class="panel-head"><div><h2>{{t("سلامت زیرساخت","Infrastructure Health")}}</h2><small>Nodes · Inbounds · Clients</small></div></div>
<div class="health-row"><span class="health-icon nodes">▤</span><div><b>{{t("نودها","Nodes")}}</b><small>{{nodeOnline}} {{t("آنلاین","online")}} · {{nodeOffline}} {{t("خارج از دسترس","offline")}}</small></div><strong :class="nodeOffline ? 'bad' : ''">{{nodeOffline ? t("نیازمند بررسی","Attention") : t("سالم","Healthy")}}</strong></div>
<div class="health-row"><span class="health-icon plans">◎</span><div><b>{{t("اینباند‌ها","Inbounds")}}</b><small>{{inboundActive}} {{t("فعال","active")}} · {{inboundRows.length - inboundActive}} {{t("غیرفعال","inactive")}}</small></div><strong :class="inboundRows.length - inboundActive ? 'bad' : ''">{{inboundRows.length - inboundActive ? t("بررسی شود","Review") : t("سالم","Healthy")}}</strong></div>
<div class="health-row"><span class="health-icon users">♟</span><div><b>{{t("کلاینت‌ها","Clients")}}</b><small>{{clientActive}} {{t("فعال","active")}} · {{clientRows.length-clientActive}} {{t("Revoke شده","revoked")}}</small></div><strong>{{t("آماده","Ready")}}</strong></div>
</div>
</div>
<div class="dashboard-grid lower"><div class="panel activity-card"><div class="panel-head"><div><h2>{{t("فعالیت‌های اخیر","Recent Activity")}}</h2><small>Audit Logs</small></div><button class="link" @click="section='audit'">{{t("مشاهده همه","View all")}} ›</button></div>
<div v-if="recentActivity.length" class="activity"><div v-for="x in recentActivity" :key="x.id"><span class="activity-icon" :class="activityTone(x)">{{activityTone(x)==='danger'?'!':activityTone(x)==='primary'?'◆':'✓'}}</span><div><b>{{activityLabel(x)}}</b><small>{{x.resource||x.actor_email||me.role}}</small></div><time>{{x.created_at}}</time><i :class="{danger:activityTone(x)==='danger'}"></i></div></div><div v-else class="dashboard-empty">{{t("هنوز فعالیتی ثبت نشده است","No activity has been recorded yet")}}</div></div>
<div class="panel quick-card"><div class="panel-head"><div><h2>{{t("دسترسی سریع","Quick Actions")}}</h2><small>Quick Actions</small></div></div><button @click="section='nodes'"><span>▤</span>{{t("مدیریت نودها","Manage Nodes")}} <b>›</b></button><button @click="section='inbounds'"><span>◎</span>{{t("مدیریت اینباند‌ها","Manage Inbounds")}} <b>›</b></button><button @click="section='clients'"><span>♟</span>{{t("مدیریت کلاینت‌ها","Manage Clients")}} <b>›</b></button><button @click="section='traffic'"><span>⌁</span>{{t("ترافیک و سهمیه","Traffic & Quota")}} <b>›</b></button></div></div>
<div class="dashboard-foot"><span>PRIMEVPN v1.0.0</span><span>{{t("آخرین بروزرسانی با Refresh انجام می‌شود","Use Refresh to fetch the latest control-plane data")}}</span></div>
</section>
<section v-else-if="section==='nodes'"><div class="nodes-page">
<div class="nodes-head"><div><span class="eyebrow">INFRASTRUCTURE MANAGEMENT</span><h1>نودها</h1><p>مدیریت VPS، اتصال Agent، سلامت سرویس و ظرفیت زیرساخت VPN</p></div><button v-if="me.role!=='tenant_operator'" class="primary" @click="modal='node'">+ نود جدید</button></div>
<div class="stats node-stats"><article><small>کل نودها</small><strong>{{nodeRows.length}}</strong><em>Infrastructure</em></article><article><small>آنلاین</small><strong>{{nodeOnline}}</strong><em>READY / DEGRADED</em></article><article><small>آفلاین</small><strong>{{nodeOffline}}</strong><em>نیازمند بررسی</em></article><article><small>Inbound فعال</small><strong>{{inboundActive}}</strong><em>روی کل نودها</em></article></div>
<div class="panel node-filters"><div class="filter-grid node-filter-grid"><input v-model="nodeSearch" placeholder="جستجو نام، IP یا Agent URL"><select v-model="nodeStateFilter"><option value="">همه وضعیت‌ها</option><option value="READY">READY</option><option value="DEGRADED">DEGRADED</option><option value="INSTALLING">INSTALLING</option><option value="PROVISION_FAILED">PROVISION FAILED</option><option value="DISABLED">DISABLED</option></select><button class="icon" @click="nodeSearch='';nodeStateFilter=''">پاک کردن فیلتر</button></div></div>
<div class="node-grid"><article v-for="n in filteredNodeRows" :key="n.id" class="node-card"><div class="node-card-head"><div><span class="node-icon">⌁</span><div class="node-title"><b>{{n.name}}</b><small>{{n.id}}</small></div></div><span class="node-state" :class="String(n.state||'').toLowerCase()"><i></i>{{n.state}}</span></div>
<div class="node-main"><div><small>VPS / Address</small><b>{{n.address}}</b></div><div><small>Agent</small><b>{{n.agent_url||'ثبت نشده'}}</b></div><div><small>آخرین ارتباط</small><b>{{n.last_seen_at?new Date(n.last_seen_at).toLocaleString('fa-IR'):'هنوز ثبت نشده'}}</b></div><div><small>Capabilities</small><b>{{n.capabilities?Object.keys(n.capabilities).join(' · '):'—'}}</b></div></div>
<div class="node-health"><span><i :class="{ok:n.state==='READY'||n.state==='DEGRADED'}"></i>Control Plane</span><span><i :class="{ok:!!n.agent_url}"></i>Agent</span><span><i :class="{ok:n.last_seen_at}"></i>Heartbeat</span></div>
<div class="node-card-actions"><button v-if="me.role!=='tenant_operator'" class="icon" @click="provision(n.id)">Provision / Sync</button><button class="icon" @click="openNodeDetail(n)">جزئیات</button></div></article><div v-if="!filteredNodeRows.length" class="empty node-empty">نودی با این فیلتر پیدا نشد.</div></div>
</div></section>
<section v-else-if="section==='inbounds'"><div class="inbounds-page">
<div class="inbounds-head"><div><span class="eyebrow">INBOUND MANAGEMENT</span><h1>این‌باندها</h1><p>مدیریت WireGuard، AmneziaWG و OpenVPN؛ وضعیت، پورت، کلاینت‌ها و Sync هر Inbound</p></div><button v-if="me.role!=='tenant_operator'" class="primary" @click="resetInboundForm();modal='inbound'">+ اینباند جدید</button></div>
<div class="stats inbound-stats"><article><span class="stat-icon plans">◎</span><small>کل اینباندها</small><strong>{{inboundRows.length}}</strong><em>{{inboundRows.length-inboundDisabled}} فعال</em></article><article><span class="stat-icon nodes">▤</span><small>WireGuard / AWG</small><strong>{{inboundRows.filter(x=>x.protocol==='wireguard'||x.protocol==='amneziawg').length}}</strong><em>VPN tunnels</em></article><article><span class="stat-icon traffic">⌁</span><small>OpenVPN</small><strong>{{inboundRows.filter(x=>x.protocol==='openvpn').length}}</strong><em>UDP / TLS</em></article><article><span class="stat-icon users">♟</span><small>کلاینت‌های متصل</small><strong>{{clientOnlineCount}}</strong><em>Session آنلاین</em></article></div>
<div class="panel inbound-filters"><div class="filter-grid inbound-filter-grid"><input v-model="inboundSearch" placeholder="جستجو نام، Protocol، Interface، IP یا Network"><select v-model="inboundProtocolFilter"><option value="">همه پروتکل‌ها</option><option value="wireguard">WireGuard</option><option value="amneziawg">AmneziaWG</option><option value="openvpn">OpenVPN</option></select><select v-model="inboundStateFilter"><option value="">همه وضعیت‌ها</option><option value="active">ACTIVE</option><option value="ready">READY</option><option value="disabled">DISABLED</option></select><button class="icon" @click="inboundSearch='';inboundProtocolFilter='';inboundStateFilter=''">پاک کردن فیلتر</button></div></div>
<div class="inbound-grid"><article v-for="x in filteredInboundRows" :key="x.id" class="inbound-card">
<div class="inbound-card-head"><div><span class="inbound-icon" :class="String(x.protocol).toLowerCase()">{{x.protocol==='openvpn'?'O':'W'}}</span><div><b>{{x.name}}</b><small>{{x.protocol}}</small></div></div><span class="inbound-state" :class="String(x.desired_state||x.state||'').toLowerCase()"><i></i>{{x.desired_state||x.state||'UNKNOWN'}}</span></div>
<div class="inbound-meta"><div><small>Port</small><b>{{x.listen_port}}</b></div><div><small>Interface</small><b>{{x.interface}}</b></div><div><small>Address</small><b>{{x.address}}</b></div><div><small>Network</small><b>{{x.network}}</b></div></div>
<div class="inbound-usage"><div><span><b>{{inboundClientsCount(x.id)}}</b><small>کلاینت</small></span><span><b>{{inboundOnlineCount(x.id)}}</b><small>آنلاین</small></span><span><b>{{x.enabled===false?'خاموش':'فعال'}}</b><small>Runtime</small></span></div><div class="inbound-node"><small>Node ID</small><b>{{x.node_id}}</b></div></div>
<div class="inbound-actions"><button class="icon" @click="openInboundDetail(x)">جزئیات</button><button class="icon" @click="act(()=>inbounds.sync(x.id),'Inbound synced')">Sync</button><button v-if="me.role!=='tenant_operator'" class="icon" @click="openInboundEdit(x)">ویرایش</button><button v-if="me.role!=='tenant_operator'" class="icon danger-btn" @click="act(()=>inbounds.remove(x.id),'Inbound removed')">Delete</button></div>
</article><div v-if="!filteredInboundRows.length" class="panel empty inbound-empty">اینباندی با این فیلتر پیدا نشد.</div></div>
</div></section>
<section v-else-if="section==='clients'"><div class="clients-page">
<div class="clients-head"><div><span class="eyebrow">CLIENT MANAGEMENT</span><h1>کلاینت‌ها</h1><p>ساخت، سهمیه، زمان انقضا، ترافیک، دستگاه و فایل کانفیگ هر کلاینت</p></div><button v-if="me.role!=='tenant_operator'" class="primary" @click="resetClientForm();modal='client'">+ کلاینت جدید</button></div>
<div class="stats client-stats"><article><small>کل کلاینت‌ها</small><strong>{{clientRows.length}}</strong><em>{{clientActive}} فعال</em></article><article><small>آنلاین</small><strong>{{clientOnlineCount}}</strong><em>Session فعال</em></article><article><small>ترافیک کل</small><strong>{{formatBytes(clientTrafficTotal)}}</strong><em>IN + OUT</em></article><article><small>نیازمند بررسی</small><strong>{{clientQuotaWarnings+clientExpiringCount}}</strong><em>{{clientQuotaWarnings}} سهمیه · {{clientExpiringCount}} انقضا</em></article></div>
<div class="panel client-filters"><div class="filter-grid"><input v-model="clientFilters.search" placeholder="جستجو نام، IP، Inbound یا Node"><select v-model="clientFilters.status"><option value="">همه وضعیت‌ها</option><option value="ACTIVE">فعال</option><option value="EXPIRED">منقضی</option><option value="REVOKED">Revoke</option><option value="SUSPENDED">معلق</option></select><select v-model="clientFilters.protocol"><option value="">همه پروتکل‌ها</option><option value="wireguard">WireGuard</option><option value="amneziawg">AmneziaWG</option><option value="openvpn">OpenVPN</option></select><select v-model="clientFilters.inbound_id"><option value="">همه Inboundها</option><option v-for="i in inboundRows" :value="i.id">{{i.name}} · {{i.protocol}}</option></select><select v-model="clientFilters.online"><option value="">همه اتصال‌ها</option><option value="true">آنلاین</option><option value="false">آفلاین</option></select><button class="icon" @click="clientFilters={search:'',status:'',protocol:'',inbound_id:'',online:''}">پاک کردن فیلتر</button></div></div>
<div class="panel page client-table-panel"><div class="table client-table"><div class="tr th"><span>کلاینت</span><span>Inbound / Node</span><span>IP</span><span>ترافیک IN / OUT</span><span>سهمیه / زمان</span><span>وضعیت</span><span>عملیات</span></div><div v-if="filteredClientRows.length===0" class="empty">کلاینتی با این فیلتر پیدا نشد.</div><div v-for="x in filteredClientRows" :key="x.id" class="tr client-row"><span><b>{{x.name}}</b><small>{{x.protocol}} · {{x.devices_count}} device</small></span><span><b>{{x.inbound_name}}</b><small>{{x.node_name}} : {{x.listen_port}}</small></span><span>{{x.assigned_address}}</span><span><b>↓ {{formatBytes(x.traffic_in)}}</b><small>↑ {{formatBytes(x.traffic_out)}}</small></span><span><b>{{x.quota_total?formatBytes(x.quota_used)+" / "+formatBytes(x.quota_total):"بدون سقف"}}</b><small>{{x.expires_at?new Date(x.expires_at).toLocaleString('fa-IR'):"بدون انقضا"}}</small></span><span><i class="status-dot" :class="{online:x.online}"></i>{{x.online?'آنلاین':x.status}}</span><span class="row-actions"><button class="icon" @click="openClientDetail(x)">جزئیات</button><button class="icon" @click="issueConfig(x.id)">دانلود</button><button class="icon" @click="openClientEdit(x)" :disabled="x.status==='REVOKED'">ویرایش</button><button v-if="x.status!=='REVOKED'" class="icon danger-btn" @click="revokeClient(x.id)">Revoke</button></span></div></div></div>
</div></section>
<section v-else-if="section==='traffic'"><div class="grid2"><div class="panel"><h2>Traffic</h2><strong>{{((trafficData.total_bytes||0)/1099511627776).toFixed(2)}} TB</strong><p>IN: {{((trafficData.bytes_in||0)/1073741824).toFixed(2)}} GB</p><p>OUT: {{((trafficData.bytes_out||0)/1073741824).toFixed(2)}} GB</p></div><div class="panel"><h2>Quota</h2><button v-if="me.role!=='tenant_operator'" class="primary" @click="modal='quota'">تنظیم سهمیه</button></div></div></section>
<section v-else-if="section==='admins'"><div class="panel page"><div class="panel-head"><h2>مدیران و RBAC</h2><button v-if="me.role!=='tenant_operator'" class="primary" @click="modal='admin'">+ مدیر</button></div><div class="table"><div class="tr th"><span>Email</span><span>Role</span><span>Enabled</span><span></span></div><div class="tr" v-for="a in adminRows" :key="a.id"><span>{{a.email}}</span><span>{{a.role}}</span><span>{{a.enabled?'YES':'NO'}}</span><span></span></div></div></div></section>
<section v-else-if="section==='audit'"><div class="panel page"><h2>Audit Logs</h2><div class="table"><div class="tr th"><span>Action</span><span>Resource</span><span>Result</span><span>Time</span></div><div class="tr" v-for="x in auditRows" :key="x.id"><span>{{x.action}}</span><span>{{x.resource}}</span><span>{{x.result}}</span><span>{{x.created_at}}</span></div></div></div></section>
<section v-else><div class="panel page"><h2>Settings</h2><div class="empty">تنظیمات امنیتی و عملیاتی از طریق Environment/Control Plane مدیریت می‌شوند.</div></div></section>
</main>
</div>
<div v-if="modal" class="modal-backdrop"><div class="modal">
<button class="close" @click="modal=null">×</button>
<div v-if="modal==='artifact'"><h2>Config Artifact</h2><p>{{artifact?.protocol}} · {{artifactName}}</p><textarea class="artifact" readonly :value="artifact?.payload"></textarea><div class="grid2"><button class="primary wide" @click="downloadArtifact">دانلود فایل</button><button class="icon wide" @click="copyArtifact">کپی Config</button></div></div><div v-if="modal==='mfa'"><h2>تأیید MFA</h2><input v-model="mfaCode" inputmode="numeric" placeholder="کد ۶ رقمی"><button class="primary wide" @click="verifyMfa">تأیید</button></div>
<div v-if="modal==='node'"><h2>{{t("افزودن VPS / Node","Add VPS / Node")}}</h2><p class="modal-help">{{t("IP و اطلاعات SSH را وارد کن؛ PRIMEVPN نصب Node Agent و ابزارهای VPN را خودکار انجام می‌دهد.","Enter the VPS IP and SSH credentials; PRIMEVPN will install the Node Agent and VPN tools automatically.")}}</p><input v-model="nodeForm.name" placeholder="Name"><input v-model="nodeForm.address" placeholder="VPS Public IP"><div class="grid2"><input v-model.number="nodeForm.ssh_port" type="number" placeholder="SSH Port"><input v-model="nodeForm.ssh_username" placeholder="SSH Username"></div><input v-model="nodeForm.ssh_password" type="password" autocomplete="new-password" placeholder="SSH Password"><button class="primary wide" @click="act(()=>nodes.autoProvision(nodeForm),t('Node نصب و آماده شد','Node installed and ready'))">{{t("نصب و اتصال خودکار","Install & Connect Automatically")}}</button><small class="security-note">{{t("رمز SSH فقط برای همین عملیات استفاده می‌شود و در دیتابیس ذخیره نمی‌شود.","SSH password is used only for this installation and is not stored in the database.")}}</small></div>
<div v-if="modal==='inbound'"><h2>{{inboundEditingId?'ویرایش Inbound':'Inbound جدید'}}</h2><p class="modal-help">پروتکل، Node و مشخصات شبکه را تنظیم کن. تغییر Protocol برای Inbound موجود مجاز نیست.</p><select v-model="inboundForm.node_id"><option value="">Node</option><option v-for="n in nodeRows" :value="n.id">{{n.name}}</option></select><select v-model="inboundForm.protocol" :disabled="!!inboundEditingId"><option value="wireguard">WireGuard</option><option value="amneziawg">AmneziaWG</option><option value="openvpn">OpenVPN</option></select><input v-model="inboundForm.name" placeholder="نام Inbound"><div class="grid2"><input v-model.number="inboundForm.listen_port" type="number" placeholder="Port"><input v-model="inboundForm.interface" placeholder="Interface"></div><div class="grid2"><input v-model="inboundForm.address" placeholder="Address/CIDR"><input v-model="inboundForm.network" placeholder="Network/CIDR"></div><input v-model="inboundForm.dns" placeholder="DNS"><button class="primary wide" :disabled="loading" @click="saveInbound">{{loading?'در حال ذخیره…':(inboundEditingId?'ذخیره تغییرات':'ساخت Inbound')}}</button></div>
<div v-if="modal==='inbound-detail'"><h2>{{clientDetail?.name}}</h2><div class="detail-grid"><div><small>Protocol</small><b>{{clientDetail?.protocol}}</b></div><div><small>State</small><b>{{clientDetail?.desired_state||clientDetail?.state}}</b></div><div><small>Node ID</small><b>{{clientDetail?.node_id}}</b></div><div><small>Port</small><b>{{clientDetail?.listen_port}}</b></div><div><small>Interface</small><b>{{clientDetail?.interface}}</b></div><div><small>Address</small><b>{{clientDetail?.address}}</b></div><div><small>Network</small><b>{{clientDetail?.network}}</b></div><div><small>DNS</small><b>{{clientDetail?.dns||'—'}}</b></div></div><div class="inbound-modal-summary"><span><b>{{inboundClientsCount(clientDetail?.id)}}</b><small>کلاینت</small></span><span><b>{{inboundOnlineCount(clientDetail?.id)}}</b><small>آنلاین</small></span><span><b>{{clientDetail?.enabled===false?'خاموش':'فعال'}}</b><small>Runtime</small></span></div><div class="grid2"><button class="primary wide" @click="modal=null;act(()=>inbounds.sync(clientDetail.id),'Inbound synced')">Sync / Apply</button><button v-if="me.role!=='tenant_operator'" class="icon wide" @click="modal=null;openInboundEdit(clientDetail)">ویرایش</button></div></div>
<div v-if="modal==='node-detail'"><h2>{{clientDetail?.name}}</h2><div class="detail-grid"><div><small>Address</small><b>{{clientDetail?.address}}</b></div><div><small>State</small><b>{{clientDetail?.state}}</b></div><div><small>Agent URL</small><b>{{clientDetail?.agent_url||'—'}}</b></div><div><small>Node ID</small><b>{{clientDetail?.id}}</b></div><div><small>آخرین Heartbeat</small><b>{{clientDetail?.last_seen_at?new Date(clientDetail.last_seen_at).toLocaleString('fa-IR'):'—'}}</b></div><div><small>Capabilities</small><b>{{clientDetail?.capabilities?Object.keys(clientDetail.capabilities).join(' · '):'—'}}</b></div></div><div class="node-health node-modal-health"><span><i :class="{ok:clientDetail?.state==='READY'||clientDetail?.state==='DEGRADED'}"></i>Control Plane</span><span><i :class="{ok:!!clientDetail?.agent_url}"></i>Agent</span><span><i :class="{ok:!!clientDetail?.last_seen_at}"></i>Heartbeat</span></div><button v-if="me.role!=='tenant_operator'" class="primary wide" @click="modal=null;provision(clientDetail.id)">Provision / Sync دوباره</button></div>
<div v-if="modal==='client'"><h2>Client جدید</h2><p class="modal-help">کلاینت ساخته می‌شود، Credential امن تولید می‌شود و فایل WireGuard/AmneziaWG یا OpenVPN برای دانلود آماده می‌شود.</p><select v-model="clientForm.inbound_id"><option value="">Inbound مورد نظر</option><option v-for="i in inboundRows" :value="i.id">{{i.name}} / {{i.protocol}}</option></select><input v-model="clientForm.name" placeholder="نام کلاینت"><input v-model="clientForm.assigned_address" placeholder="10.10.0.2/32"><div class="grid2"><input v-model="clientForm.expires_at" type="datetime-local" placeholder="زمان انقضا"><input v-model.number="clientForm.warning_ratio" type="number" min="1" max="100" placeholder="هشدار سهمیه %"></div><div class="grid3"><input v-model="clientForm.total_gb" inputmode="decimal" placeholder="حجم کل (GB)"><input v-model="clientForm.daily_gb" inputmode="decimal" placeholder="سقف روزانه (GB)"><input v-model="clientForm.monthly_gb" inputmode="decimal" placeholder="سقف ماهانه (GB)"></div><input v-model="clientForm.max_devices" type="number" min="1" placeholder="حداکثر دستگاه"><button class="primary wide" :disabled="loading" @click="createClient">{{loading?'در حال ساخت…':'ساخت + تولید فایل کانفیگ'}}</button></div>
<div v-if="modal==='client-edit'"><h2>ویرایش Client</h2><input v-model="clientForm.name" placeholder="نام کلاینت"><input v-model="clientForm.expires_at" type="datetime-local"><div class="grid3"><input v-model="clientForm.total_gb" placeholder="حجم کل (GB)"><input v-model="clientForm.daily_gb" placeholder="سقف روزانه (GB)"><input v-model="clientForm.monthly_gb" placeholder="سقف ماهانه (GB)"></div><input v-model="clientForm.max_devices" type="number" min="1" placeholder="حداکثر دستگاه"><input v-model.number="clientForm.warning_ratio" type="number" min="1" max="100" placeholder="هشدار سهمیه %"><button class="primary wide" @click="saveClientEdit">ذخیره تغییرات</button></div>
<div v-if="modal==='client-detail'"><h2>{{clientDetail?.name}}</h2><div class="detail-grid"><div><small>Inbound</small><b>{{clientDetail?.inbound_name}}</b></div><div><small>Protocol</small><b>{{clientDetail?.protocol}}</b></div><div><small>IP</small><b>{{clientDetail?.assigned_address}}</b></div><div><small>Node</small><b>{{clientDetail?.node_name}}</b></div><div><small>IN</small><b>{{formatBytes(clientDetail?.traffic_in||0)}}</b></div><div><small>OUT</small><b>{{formatBytes(clientDetail?.traffic_out||0)}}</b></div><div><small>تاریخ ساخت</small><b>{{new Date(clientDetail?.created_at).toLocaleString('fa-IR')}}</b></div><div><small>انقضا</small><b>{{clientDetail?.expires_at?new Date(clientDetail.expires_at).toLocaleString('fa-IR'):'بدون انقضا'}}</b></div></div><div class="quota-detail"><b>سهمیه</b><span>{{clientDetail?.quota_total?formatBytes(clientDetail.quota_used)+' / '+formatBytes(clientDetail.quota_total):'بدون سقف'}} · روزانه {{clientDetail?.quota_daily?formatBytes(clientDetail.quota_daily):'—'}} · ماهانه {{clientDetail?.quota_monthly?formatBytes(clientDetail.quota_monthly):'—'}} · دستگاه {{clientDetail?.max_devices||'∞'}}</span><i>{{clientDetail?.quota_state||'NORMAL'}}</i></div><h3>دستگاه‌ها ({{clientDevices.length}})</h3><div class="device-list"><div v-for="d in clientDevices" :key="d.id"><b>{{d.assigned_address||'—'}}</b><small>{{d.fingerprint}}</small><time>{{d.last_seen_at?new Date(d.last_seen_at).toLocaleString('fa-IR'):'هنوز متصل نشده'}}</time></div><div v-if="!clientDevices.length" class="empty">هنوز دستگاهی ثبت نشده است.</div></div><div class="grid2"><button class="primary wide" @click="issueConfig(clientDetail.id)">تولید / دانلود Config</button><button v-if="clientDetail?.status!=='REVOKED'" class="icon wide danger-btn" @click="modal=null;revokeClient(clientDetail.id)">Revoke</button></div></div>
<div v-if="modal==='admin'"><h2>Admin جدید</h2><input v-model="adminForm.email" placeholder="Email"><input v-model="adminForm.password" type="password" placeholder="Password ≥ 12 chars"><select v-model="adminForm.role"><option value="tenant_operator">Operator</option><option value="tenant_manager">Manager</option></select><button class="primary wide" @click="act(()=>admins.create(adminForm),'Admin ساخته شد')">ساخت</button></div>
<div v-if="modal==='quota'"><h2>Quota</h2><select v-model="quotaForm.client_id"><option value="">Client</option><option v-for="c in clientRows" :value="c.id">{{c.name}}</option></select><input v-model="quotaForm.total_bytes" type="number" placeholder="Total bytes"><input v-model="quotaForm.daily_bytes" type="number" placeholder="Daily bytes"><input v-model="quotaForm.monthly_bytes" type="number" placeholder="Monthly bytes"><input v-model="quotaForm.max_devices" type="number" placeholder="Max devices"><input v-model.number="quotaForm.warning_ratio" type="number" placeholder="Warning %"><button class="primary wide" @click="act(()=>quotas.set({...quotaForm,total_bytes:quotaForm.total_bytes?Number(quotaForm.total_bytes):null,daily_bytes:quotaForm.daily_bytes?Number(quotaForm.daily_bytes):null,monthly_bytes:quotaForm.monthly_bytes?Number(quotaForm.monthly_bytes):null,max_devices:quotaForm.max_devices?Number(quotaForm.max_devices):null}),'Quota ذخیره شد')">ذخیره</button></div>
</div></div>
</template>